"""نسخه ۲ آموزش ۰۱ تندخوانی: متن حجیم و گویا + ۱۷ تصویر مفهومی (هر تکنیک یک تصویر)"""
import json, base64, io, re, os
from PIL import Image

SRC_HTML = "/home/user/آموزشگاه/01-speed-reading.html"
IMG_DIR = "/home/user/آموزشگاه/images/01-speed-reading"

def data_uri(fname, max_w=720, q=65):
    im = Image.open(f"{IMG_DIR}/{fname}").convert("RGB")
    if im.width > max_w:
        im = im.resize((max_w, int(im.height * max_w / im.width)), Image.LANCZOS)
    buf = io.BytesIO()
    im.save(buf, "JPEG", quality=q, optimize=True)
    return "data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode()

IMG = {i: data_uri(f"img-{i:02d}.jpg") for i in range(1, 18)}

