def fig(n):
    parts = CAPTIONS[n].split("ـ")
    return (f'<figure><img src="{IMG[n]}" alt="{CAPTIONS[n]}" loading="lazy">'
            f'<figcaption><span class="ref">{parts[0].strip()}</span> ـ {"ـ".join(parts[1:]).strip()}</figcaption></figure>')

def tech(num, name):
    return f'<p class="tech"><span class="tnum">تکنیک {num}</span>{name}</p>'

def kc(num, name):
    return f'<p class="tech"><span class="tnum">مفهوم {num}</span>{name}</p>'

def ref(n):
    fa = ["۱","۲","۳","۴","۵","۶","۷","۸","۹","۱۰","۱۱","۱۲","۱۳","۱۴","۱۵","۱۶","۱۷"][n-1]
    return f'<span class="ref">تصویر شماره {fa}</span>'

